args.command:
echo "=== xtb charge info in log ==="; grep -iE "charge|uhf|\\$chrg|\\$set" complex_opt.log | head -20; echo "=== analyze complex_opt.xyz ==="; python3 - <<'EOF'
import math
lines=open('complex_opt.xyz').read().splitlines()
n=int(lines[0]); atoms=[]
for i in range(n):
    p=lines[2+i].split(); atoms.append((p[0],float(p[1]),float(p[2]),float(p[3])))
def dist(a,b): return math.dist(a[1:],b[1:])
# find Pd and N and P and O
for i,a in enumerate(atoms):
    if a[0] in ('Pd',):
        pd=i
print('Pd index',pd,atoms[pd])
print('\nNeighbors of Pd (d<2.8A):')
for i,a in enumerate(atoms):
    d=dist(atoms[pd],a)
    if i!=pd and d<2.8: print(' ',i,a[0],round(d,3))
# N atom
ni=[i for i,a in enumerate(atoms) if a[0]=='N'][0]
print('\nN index',ni,atoms[ni],'neighbors d<1.7:')
for i,a in enumerate(atoms):
    d=dist(atoms[ni],a)
    if i!=ni and d<1.7: print(' ',i,a[0],round(d,3))
# fragment atoms = those not in xantphos(0..73)+Pd? assume xantphos=74 atoms (0..73), Pd=74, fragment=75..99
print('\nfragment atoms 75..99:')
for i in range(75,n):
    print(i,atoms[i])
EOF
